package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class GradeSevenWholeFractionDivisionScopeTest {
 @Test public void finalFormatsAndPublicPartErrorsDoNotMutateStudentRaw(){
  assertEquals(0,FractionInput.errorPart(null,"1/2"));assertEquals(0,FractionInput.errorPart(null,null));
  Question q=new Question("fracWholeDiv","2 ÷ 4/3","poison","999");Checker c=new Checker();for(String raw:List.of("3/2","6/4","1.5"))assertTrue(c.check(q,List.of(),List.of(raw)).correct());for(String raw:List.of("","(1.5)","1+0.5","3/2+0"))assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of(raw)).status);
  q.answerFormat="fraction";assertTrue(c.check(q,List.of(),List.of("6/4")).correct());assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("1.5")).status);q.answerFormat="decimal";assertTrue(c.check(q,List.of(),List.of("1.5")).correct());assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("3/2")).status);q.answerFormat="";
  List<String>raw=new ArrayList<>(List.of("4/2","3/4","4/4","6/4"));List<String>before=List.copyOf(raw);assertEquals(1,FractionInput.errorPart(q,raw.get(0)));assertEquals(2,FractionInput.errorPart(q,raw.get(1)));assertEquals(0,FractionInput.errorPart(q,raw.get(2)));assertEquals(0,FractionInput.errorPart(q,raw.get(3)));assertEquals(before,raw);assertEquals("poison",q.expression);assertArrayEquals(new String[]{"999"},q.answers);
  Question guard=new Question("fracWholeDiv","1".repeat(1100)+" ÷ 1/2","poison","999");assertNull(PrimaryWholeFractionDivision.read(guard));assertEquals(Checker.Status.INPUT_NEEDED,c.check(guard,List.of(),List.of("999")).status);
 }
 @Test public void generalPublicHelpPreservesAllLegacyFramesAndCompletedDraft(){
  String[]labels={"첫 분자 a = ","첫 분모 b = ","둘째 분자 c = ","둘째 분모 d = ","역수의 분자 e = d = ","역수의 분모 f = c = ","계산한 분자 N = a × e = ","계산한 분모 D = b × f = ","최대공약수 g = gcd(N, D) = ","최종 분자 = N ÷ g = ","최종 분모 = D ÷ g = "};
  String[]instructions={"자연수를 분자로 쓰세요.","자연수는 분모가 1인 분수로 쓸 수 있습니다. 분모를 쓰세요.","두 번째 분수의 분자를 쓰세요.","두 번째 분수의 분모를 쓰세요.","나누는 분수를 뒤집어 역수의 분자를 쓰세요.","역수의 분모에 나누는 수의 분자를 쓰세요.","분자끼리 곱하세요.","분모끼리 곱하세요.","계산한 분자와 분모를 모두 나눌 수 있는 가장 큰 수를 구하세요.","계산한 분자를 최대공약수로 나누세요.","분모도 같은 최대공약수로 나누세요."};
  for(String raw:List.of("2 ÷ 1/4","0 ÷ 1/4","2 ÷ 5/4","2 ÷ 4/4","2 ÷ 2/4","1234 ÷ 5678/9012","12345678901234567890 ÷ 2/3")){
   Question q=new Question("fracWholeDiv",raw,"poison","999");String prompt=q.prompt;var p=PrimaryWholeFractionDivision.read(q);assertNotNull(p);java.math.BigInteger n=p.k.multiply(p.d),d=p.c,g=n.gcd(d);String[]values={p.k.toString(),"1",p.c.toString(),p.d.toString(),p.d.toString(),p.c.toString(),n.toString(),d.toString(),g.toString(),n.divide(g).toString(),d.divide(g).toString()};HelpPlan h=HelpPlan.forQuestion(q);assertNotNull(raw,h);assertEquals(11,h.size());assertFalse(h.canTransfer());assertEquals("fraction-product-relations-v1",q.studyGuide.teachingVersion);assertEquals(Integer.valueOf(9),q.studyGuide.resultNumeratorFrame);assertEquals(Integer.valueOf(10),q.studyGuide.resultDenominatorFrame);
   for(int i=0;i<11;i++){assertEquals(instructions[i],h.step(i).instruction);assertEquals(labels[i],h.step(i).before);assertEquals("",h.step(i).after);assertTrue(h.step(i).options.isEmpty());assertEquals(values[i],q.studyGuide.frames.get(i).expected);assertTrue(h.step(i).accepts(values[i]));}
   HelpPlan.Draft old=new HelpPlan.Draft();old.questionId=q.id;old.teachingVersion="fraction-product-relations-v1";old.entries=new ArrayList<>(Arrays.asList(values));old.stage=11;var restored=h.restore(old.copy(),q.id);assertEquals(11,restored.stage);assertEquals(Arrays.asList(values),restored.entries.subList(0,11));assertEquals(prompt,q.prompt);assertEquals("poison",q.expression);assertArrayEquals(new String[]{"999"},q.answers);assertTrue(new Checker().check(q,List.of(),List.of(new Rational(p.k,java.math.BigInteger.ONE).div(new Rational(p.c,p.d)).toString())).correct());
  }
 }
 @Test public void actualRoutePreservesNaturalWholePromptAndElevenBlankFrames(){Learning.Profile p=new Learning.Profile();GlobalCurriculum.chooseCountry(p,"NA");GlobalCurriculum.choosePack(p,"na-nied-primary-2024-v1");assertTrue(GlobalCurriculum.pack(p).inGrade("fracWholeDiv",7));CurriculumLimits l=GlobalCurriculum.limits("na-nied-primary-2024-v1","fracWholeDiv",7);Generator gen=new Generator(new Random(353));List<String>recent=new ArrayList<>();for(int i=0;i<100;i++){Question q=gen.next("fracWholeDiv",recent,false,l);assertTrue(l.allows(q));assertFalse(recent.contains(q.signature()));recent.add(q.signature());var g=PrimaryWholeFractionDivision.read(q);assertNotNull(q.prompt,g);Rational expected=new Rational(g.k,java.math.BigInteger.ONE).div(new Rational(g.c,g.d));q.expression="poison";q.answers=new String[]{"999"};assertTrue(new Checker().check(q,List.of(),List.of(expected.toString())).correct());assertFalse(new Checker().check(q,List.of(),List.of("999")).correct());var h=HelpPlan.forQuestion(q);assertEquals(11,h.size());assertFalse(h.canTransfer());}}
 @Test public void syntaxPublicDomainAndFormatsAreNotSupplierCaps(){for(String raw:List.of("2 ÷ 1/4","2 / (1/4)","(2) / (1/4)","(2) ÷ 1/4")){Question q=new Question("fracWholeDiv",raw,"poison","999");assertNotNull(PrimaryWholeFractionDivision.read(q));assertTrue(new Checker().check(q,List.of(),List.of("8/1")).correct());}for(String[]v:new String[][]{{"0 ÷ 1/4","0/1"},{"2 ÷ 5/4","8/5"},{"2 ÷ 4/4","2/1"},{"1234 ÷ 5678/9012","11120808/5678"}})assertTrue(new Checker().check(new Question("fracWholeDiv",v[0],"poison","999"),List.of(),List.of(v[1])).correct());for(String raw:List.of("2 ÷ 0/4","2 ÷ 1/0","2 × 1/4","2/1 ÷ 1/4","((2)) / (1/4)","2 / (1/4","2 / 1/4)","-2 ÷ 1/4"))assertNull(PrimaryWholeFractionDivision.read(new Question("fracWholeDiv",raw,"","999")));Question q=new Question("fracWholeDiv","2 ÷ 4/3","poison","999");assertTrue(new Checker().check(q,List.of(),List.of("1.5")).correct());q.answerFormat="decimalValue";assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("3/2")).status);q.answerFormat="hundredthsFraction";assertTrue(new Checker().check(q,List.of(),List.of("150/100")).correct());assertEquals(Checker.Status.WRONG_ANSWER,new Checker().check(q,List.of(),List.of("3/2")).status);assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("")).status);q.answerFormat="";q.kind="reduced";assertEquals(Checker.Status.INPUT_NEEDED,new Checker().check(q,List.of(),List.of("6/4")).status);}
}
